const end = Date.now() + 40000;
const killed = [];
while (Date.now() < end) {
  const s = sdk.getState();
  if (s.dialog?.isOpen) { await bot.dismissBlockingUI(); }
  const target = sdk.findNearbyNpc(/^(Rat|Man)$/i);
  if (target) {
    const r = await bot.attack(target);
    if (!r.success) { await sdk.waitForTicks(2); continue; }
    const nm = target.name;
    const deadline = Date.now() + 20000;
    while (Date.now() < deadline) {
      const cur = sdk.getState();
      const still = (cur.nearbyNpcs||[]).some(n => n.id === target.id);
      if (!still) { killed.push(nm); break; }
      if ((cur.player.hp??10) < 4) break;
      await sdk.waitForTicks(2);
    }
  } else {
    await sdk.waitForTicks(3);
  }
}
console.log('killed attempts:', JSON.stringify(killed));
return sdk.getSkill('Hitpoints');

